head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07100_menu";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.listTpClssCd, param.ldMktTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07100_menu.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "txt_b6", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") ==='02'); } }, { id: "c_otherwise_7", fn: function(){ return (!(((dma_pageContext.get("listTpClssCd") ?? "") ==='02'))); } }, { id: "if_ldMktTpCd", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '2'); } }, { id: "if_listTpClssCd", fn: function(){ return ((dma_pageContext.get("listTpClssCd") ?? "") !== '00'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
